private array$statusLabels=['pending'=>'در انتظار تأیید','approved'=>'تأیید شده','rejected'=>'رد شده','completed'=>'پایان یافته','canceled'=>'لغو شده','rescheduled'=>'زمان‌بندی مجدد','held'=>'برگزار شده','postponed'=>'به تعویق افتاده'];
public function index(int$actor,array$f):array{$branches=$this->branches($actor);$bids=array_column($branches,'branch_id');$allowedPer=[10,20,30,50,100];$per=in_array((int)($f['perPage']??10),$allowedPer,true)?(int)$f['perPage']:10;if(!$bids)return['schedules'=>[],'branches'=>[],'terms'=>[],'classrooms'=>[],'timeRanges'=>[],'total'=>0,'page'=>1,'perPage'=>$per];$page=max(1,(int)($f['page']??1));$allBranches=DB::table('academy_branches')->whereNull('deleted_at')->count();$scope=count($bids)===$allBranches?'1=1':'c.branch_id IN ('.implode(',',array_map('intval',$bids)).')';$where=[$scope,'s.deleted_at IS NULL','b.deleted_at IS NULL','t.deleted_at IS NULL','c.deleted_at IS NULL'];$bind=[];
if(!empty($f['branch'])){$where[]='c.branch_id=?';$bind[]=(int)$f['branch'];}if(!empty($f['status'])){$where[]='b.status=?';$bind[]=$f['status'];}if(!empty($f['mode'])){$where[]='s.delivery_mode=?';$bind[]=$f['mode'];}if(!empty($f['classroom'])){$where[]='s.classroom_id=?';$bind[]=(int)$f['classroom'];}if(!empty($f['lesson'])){$where[]='c.lesson_id=?';$bind[]=(int)$f['lesson'];}if(!empty($f['date'])){$where[]='b.requested_date=?';$bind[]=$f['date'];}if(isset($f['day'])&&$f['day']!==''){$where[]='WEEKDAY(b.requested_date)=?';$bind[]=(int)$f['day'];}if(!empty($f['timeFrom'])){$where[]='b.end_time>=?';$bind[]=$f['timeFrom'];}if(!empty($f['timeTo'])){$where[]='b.start_time<=?';$bind[]=$f['timeTo'];}if(!empty($f['search'])){$where[]="(EXISTS(SELECT 1 FROM translations x WHERE x.table_name='academy_branch_course_terms' AND x.table_id=t.term_id AND x.locale='fa' AND x.field='title' AND x.value LIKE ?) OR EXISTS(SELECT 1 FROM translations x WHERE x.table_name='lessons' AND x.table_id=c.lesson_id AND x.locale='fa' AND x.field='title' AND x.value LIKE ?))";$q='%'.trim($f['search']).'%';$bind[]=$q;$bind[]=$q;}$w=implode(' AND ',$where);$count=$this->query("SELECT COUNT(1) FROM academy_branch_course_term_sessions s JOIN academy_branch_bookings b ON b.booking_id=s.booking_id JOIN academy_branch_course_terms t ON t.term_id=s.term_id JOIN academy_branch_courses c ON c.course_id=t.course_id WHERE $w",$bind,true);$offset=($page-1)*$per;
$sql="SELECT s.*,b.requested_date,b.start_time,b.end_time,b.status booking_status,t.course_id,c.branch_id,c.lesson_id,(SELECT value FROM translations WHERE table_name='academy_branch_course_terms' AND table_id=t.term_id AND locale='fa' AND field='title' AND deleted_at IS NULL ORDER BY translation_id DESC LIMIT 1) term_name,(SELECT value FROM translations WHERE table_name='lessons' AND table_id=c.lesson_id AND locale='fa' AND field='title' AND deleted_at IS NULL ORDER BY translation_id DESC LIMIT 1) lesson_name,(SELECT value FROM translations WHERE table_name='academy_branch_classrooms' AND table_id=s.classroom_id AND locale='fa' AND field='title' AND deleted_at IS NULL ORDER BY translation_id DESC LIMIT 1) classroom_name FROM academy_branch_course_term_sessions s JOIN academy_branch_bookings b ON b.booking_id=s.booking_id JOIN academy_branch_course_terms t ON t.term_id=s.term_id JOIN academy_branch_courses c ON c.course_id=t.course_id WHERE $w ORDER BY b.requested_date DESC,b.start_time DESC,s.term_session_id DESC LIMIT $offset,$per";$rows=$this->query($sql,$bind);foreach($rows as&$row)$row['session_number']=$this->sessionNumber($row);unset($row);$items=$this->enrich($rows,$branches);return['schedules'=>$items,'branches'=>$this->branchOptions($branches),'classrooms'=>$this->classroomOptions($bids),'lessons'=>$this->lessonOptions($bids),'timeRanges'=>$this->timeRangeOptions($bids),'total'=>(int)$count,'page'=>$page,'perPage'=>$per];}
public function weeklyBounds(int$actor,int$branchId=0):array{$branches=$this->branches($actor);$ids=array_map(fn($b)=>(int)$b['branch_id'],$branches);if($branchId){if(!in_array($branchId,$ids,true))throw new RuntimeException('دسترسی به شعبه ندارید.');$ids=[$branchId];}if(!$ids)return['firstDate'=>null,'lastDate'=>null];$in=implode(',',$ids);$sql="SELECT MIN(b.requested_date) first_date,MAX(b.requested_date) last_date FROM academy_branch_course_term_sessions s JOIN academy_branch_bookings b ON b.booking_id=s.booking_id JOIN academy_branch_course_terms t ON t.term_id=s.term_id JOIN academy_branch_courses c ON c.course_id=t.course_id WHERE c.branch_id IN ($in) AND s.deleted_at IS NULL AND b.deleted_at IS NULL AND t.deleted_at IS NULL AND c.deleted_at IS NULL";$r=db()->query($sql)->fetch();return['firstDate'=>$r['first_date']??null,'lastDate'=>$r['last_date']??null];}
public function save(int$actor,array$d,int$id=0):array{$session=$id?$this->session($actor,$id):null;$termId=(int)($d['termId']??($session['term_id']??0));$term=$this->term($actor,$termId);$date=(string)($d['date']??'');$start=(string)($d['startTime']??'');$end=(string)($d['endTime']??'');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||!preg_match('/^\d{2}:\d{2}$/',$start)||!preg_match('/^\d{2}:\d{2}$/',$end)||$end<=$start)throw new RuntimeException('تاریخ و بازه زمانی جلسه معتبر نیست.');$mode=($d['mode']??'in_person')==='online'?'online':'in_person';$classroom=null;if($mode==='in_person'){$classroom=(int)($d['classroomId']??0);if(!DB::table('academy_branch_classrooms')->where('classroom_id',$classroom)->where('branch_id',(int)$term['branch_id'])->whereNull('deleted_at')->first())throw new RuntimeException('کلاس حضوری معتبر نیست.');}$allowed=array_keys($this->statusLabels);$status=in_array($d['status']??'',$allowed,true)?$d['status']:'approved';return transaction(function()use($actor,$d,$id,$session,$termId,$date,$start,$end,$mode,$classroom,$status){$booking=['requested_date'=>$date,'start_time'=>$start,'end_time'=>$end,'status'=>$status,'updated_by'=>$actor];if($id){DB::table('academy_branch_bookings')->where('booking_id',(int)$session['booking_id'])->update($booking);DB::table('academy_branch_course_term_sessions')->where('term_session_id',$id)->update(['term_id'=>$termId,'classroom_id'=>$classroom,'delivery_mode'=>$mode,'updated_by'=>$actor]);}else{$students=DB::table('academy_branch_course_term_enrollments')->where('term_id',$termId)->where('type','student')->whereNull('deleted_at')->count();$bid=DB::table('academy_branch_bookings')->insertGetId(['type'=>$students>1?'group-class':'private-class','created_by'=>$actor]+$booking);$id=DB::table('academy_branch_course_term_sessions')->insertGetId(['term_id'=>$termId,'booking_id'=>$bid,'classroom_id'=>$classroom,'delivery_mode'=>$mode,'created_by'=>$actor,'updated_by'=>$actor]);}$this->setText('academy_branch_course_term_sessions',$id,'description',trim((string)($d['description']??'')),$actor);return['id'=>$id];});}
public function delete(int$actor,int$id):void{$s=$this->session($actor,$id);$now=date('Y-m-d H:i:s');transaction(function()use($actor,$id,$s,$now){DB::table('academy_branch_course_term_sessions')->where('term_session_id',$id)->update(['deleted_at'=>$now,'deleted_by'=>$actor]);DB::table('academy_branch_bookings')->where('booking_id',(int)$s['booking_id'])->update(['deleted_at'=>$now,'deleted_by'=>$actor]);});}
public function attendance(int$actor,int$id,array$d):void{$s=$this->session($actor,$id);$enrollments=DB::table('academy_branch_course_term_enrollments')->where('term_id',(int)$s['term_id'])->whereNull('deleted_at')->get();$emap=[];foreach($enrollments as$e)$emap[(int)$e['member_id']]=$e;$allowed=['present','absent','late','leave','excused_absence','online'];transaction(function()use($actor,$id,$d,$emap,$allowed){foreach(($d['attendance']??[])as$a){$mid=(int)($a['memberId']??0);if(!isset($emap[$mid]))throw new RuntimeException('عضو انتخاب‌شده متعلق به این ترم نیست.');$status=(string)($a['status']??'');if(!in_array($status,$allowed,true))throw new RuntimeException('وضعیت حضور و غیاب معتبر نیست.');$row=DB::table('academy_branch_course_term_session_attendances')->where('session_id',$id)->where('member_id',$mid)->whereNull('deleted_at')->first();$vals=['term_enrollment_id'=>(int)$emap[$mid]['term_enrollment_id'],'status'=>$status,'updated_by'=>$actor];if($row){$aid=(int)$row['session_attendance_id'];DB::table('academy_branch_course_term_session_attendances')->where('session_attendance_id',$aid)->update($vals);}else$aid=DB::table('academy_branch_course_term_session_attendances')->insertGetId(['session_id'=>$id,'member_id'=>$mid,'created_by'=>$actor]+$vals);$this->setText('academy_branch_course_term_session_attendances',$aid,'description',trim((string)($a['description']??'')),$actor);}});}
private function enrich(array$rows,array$branches):array{$termIds=array_values(array_unique(array_map(fn($r)=>(int)$r['term_id'],$rows)));$sessionIds=array_map(fn($r)=>(int)$r['term_session_id'],$rows);$people=[];if($termIds){$in=implode(',',$termIds);$sql="SELECT e.term_id,e.term_enrollment_id,e.member_id,e.type,m.user_id,COALESCE((SELECT value FROM translations WHERE table_name='users' AND table_id=m.user_id AND locale='fa' AND field='full_name' AND deleted_at IS NULL ORDER BY translation_id DESC LIMIT 1),CONCAT('عضو ',e.member_id)) name FROM academy_branch_course_term_enrollments e JOIN academy_branch_members m ON m.member_id=e.member_id WHERE e.deleted_at IS NULL AND e.term_id IN ($in) ORDER BY e.type,e.member_id";foreach(db()->query($sql)->fetchAll()as$p)$people[(int)$p['term_id']][]=$p;}$att=[];if($sessionIds){$in=implode(',',$sessionIds);$sql="SELECT a.*,(SELECT value FROM translations WHERE table_name='academy_branch_course_term_session_attendances' AND table_id=a.session_attendance_id AND locale='fa' AND field='description' AND deleted_at IS NULL ORDER BY translation_id DESC LIMIT 1) description FROM academy_branch_course_term_session_attendances a WHERE a.deleted_at IS NULL AND a.session_id IN ($in)";foreach(db()->query($sql)->fetchAll()as$a)$att[(int)$a['session_id']][(int)$a['member_id']]=$a;}$desc=[];if($sessionIds){$in=implode(',',$sessionIds);foreach(db()->query("SELECT table_id,value FROM translations WHERE table_name='academy_branch_course_term_sessions' AND locale='fa' AND field='description' AND deleted_at IS NULL AND table_id IN ($in)")->fetchAll()as$x)$desc[(int)$x['table_id']]=$x['value'];}$bmap=[];foreach($branches as$b)$bmap[(int)$b['branch_id']]=$this->tr('academy_branches',(int)$b['branch_id'],'name')?:'شعبه '.$b['branch_id'];return array_map(function($r)use($people,$att,$desc,$bmap){$sid=(int)$r['term_session_id'];$ps=$people[(int)$r['term_id']]??[];$teachers=[];$students=[];foreach($ps as$p){$a=$att[$sid][(int)$p['member_id']]??null;$x=['id'=>(int)$p['member_id'],'enrollmentId'=>(int)$p['term_enrollment_id'],'name'=>$p['name'],'status'=>$a['status']??'absent','description'=>$a['description']??''];if($p['type']==='teacher')$teachers[]=$x;elseif($p['type']==='student')$students[]=$x;}$teacherLabel=count($teachers)===1?$teachers[0]['name']:count($teachers).' مدرس';$studentLabel=count($students)===1?$students[0]['name']:count($students).' هنرجو';$number=(int)$r['session_number'];$term=$r['term_name']?:'ترم '.$r['term_id'];$status=$this->displayStatus($r);return['id'=>$sid,'termId'=>(int)$r['term_id'],'sessionNumber'=>$number,'title'=>'جلسه '.$this->ordinal($number).' '.$term.'، '.$teacherLabel,'summary'=>$studentLabel.'، '.$teacherLabel,'description'=>$desc[$sid]??'','date'=>$r['requested_date'],'day'=>$this->day($r['requested_date']),'startTime'=>substr((string)$r['start_time'],0,5),'endTime'=>substr((string)$r['end_time'],0,5),'time'=>substr((string)$r['start_time'],0,5).'-'.substr((string)$r['end_time'],0,5),'student'=>$studentLabel,'teacher'=>$teacherLabel,'students'=>$students,'teachers'=>$teachers,'lesson'=>$r['lesson_name']?:'درس '.$r['lesson_id'],'classroomId'=>(int)$r['classroom_id'],'classroom'=>$r['delivery_mode']==='online'?'کلاس آنلاین':($r['classroom_name']?:'کلاس '.$r['classroom_id']),'branchId'=>(int)$r['branch_id'],'branchName'=>$bmap[(int)$r['branch_id']]??'—','type'=>$r['delivery_mode']==='online'?'آنلاین':'حضوری','mode'=>$r['delivery_mode'],'status'=>$status['label'],'statusCode'=>$status['code'],'attendance'=>array_merge($teachers,$students)];},$rows);}
private function displayStatus(array$r):array{$date=$r['requested_date'];$now=date('H:i:s');if($date===date('Y-m-d')&&in_array($r['booking_status'],['approved','held'],true)&&$now>=($r['start_time']??'00:00:00')&&$now<=($r['end_time']??'23:59:59'))return['code'=>'in_progress','label'=>'در حال برگزاری'];if(($date>date('Y-m-d')||($date===date('Y-m-d')&&($r['start_time']??'')>$now))&&!in_array($r['booking_status'],['canceled','rejected'],true))return['code'=>'upcoming','label'=>'در انتظار برگزاری'];return['code'=>$r['booking_status'],'label'=>$this->statusLabels[$r['booking_status']]??$r['booking_status']];}
private function branches(int$a):array{$u=DB::table('users')->where('user_id',$a)->whereNull('deleted_at')->first();if(!$u)throw new RuntimeException('کاربر معتبر نیست.');if(SiteAdminAccess::allows($u))return DB::table('academy_branches')->whereNull('deleted_at')->get();if(($u['type']??'')==='branch')return DB::table('academy_branches')->where('user_id',$a)->whereNull('deleted_at')->get();$acs=array_merge(DB::table('academies')->where('user_id',$a)->whereNull('deleted_at')->get(),DB::table('academies')->where('created_by',$a)->whereNull('deleted_at')->get());$ids=array_values(array_unique(array_map(fn($x)=>(int)$x['academy_id'],$acs)));return$ids?DB::table('academy_branches')->whereIn('academy_id',$ids)->whereNull('deleted_at')->get():[];}
private function session(int$a,int$id):array{$s=DB::table('academy_branch_course_term_sessions')->where('term_session_id',$id)->whereNull('deleted_at')->first();if(!$s)throw new RuntimeException('جلسه یافت نشد.');$this->term($a,(int)$s['term_id']);return$s;}private function term(int$a,int$id):array{$bids=array_column($this->branches($a),'branch_id');$sql='SELECT t.*,c.branch_id FROM academy_branch_course_terms t JOIN academy_branch_courses c ON c.course_id=t.course_id WHERE t.term_id=? AND t.deleted_at IS NULL AND c.deleted_at IS NULL';$r=$this->query($sql,[$id])[0]??null;if(!$r||!in_array((int)$r['branch_id'],$bids,true))throw new RuntimeException('ترم معتبر نیست.');return$r;}
private function branchOptions(array$b):array{$ids=implode(',',array_map(fn($x)=>(int)$x['branch_id'],$b));if(!$ids)return[];$sql="SELECT a.branch_id id,COALESCE((SELECT value FROM translations WHERE table_name='academy_branches' AND table_id=a.branch_id AND locale='fa' AND field='name' AND deleted_at IS NULL ORDER BY translation_id DESC LIMIT 1),CONCAT('شعبه ',a.branch_id)) name FROM academy_branches a WHERE a.branch_id IN ($ids) ORDER BY a.branch_id";return array_map(fn($x)=>['id'=>(int)$x['id'],'name'=>$x['name']],db()->query($sql)->fetchAll());}private function termOptions(array$b):array{$ids=implode(',',array_map('intval',$b));if(!$ids)return[];$sql="SELECT t.term_id id,t.course_id,c.branch_id,COALESCE((SELECT value FROM translations WHERE table_name='academy_branch_course_terms' AND table_id=t.term_id AND locale='fa' AND field='title' AND deleted_at IS NULL ORDER BY translation_id DESC LIMIT 1),CONCAT('ترم ',t.term_id)) name FROM academy_branch_course_terms t JOIN academy_branch_courses c ON c.course_id=t.course_id WHERE c.branch_id IN ($ids) AND t.deleted_at IS NULL AND c.deleted_at IS NULL ORDER BY t.term_id DESC LIMIT 500";return array_map(fn($x)=>['id'=>(int)$x['id'],'courseId'=>(int)$x['course_id'],'branchId'=>(int)$x['branch_id'],'name'=>$x['name']],db()->query($sql)->fetchAll());}private function classroomOptions(array$b):array{$ids=implode(',',array_map('intval',$b));if(!$ids)return[];$sql="SELECT r.classroom_id id,r.branch_id,COALESCE((SELECT value FROM translations WHERE table_name='academy_branch_classrooms' AND table_id=r.classroom_id AND locale='fa' AND field='title' AND deleted_at IS NULL ORDER BY translation_id DESC LIMIT 1),CONCAT('کلاس ',r.classroom_id)) name FROM academy_branch_classrooms r WHERE r.branch_id IN ($ids) AND r.deleted_at IS NULL ORDER BY r.classroom_id";return array_map(fn($x)=>['id'=>(int)$x['id'],'branchId'=>(int)$x['branch_id'],'name'=>$x['name']],db()->query($sql)->fetchAll());}private function lessonOptions(array$b):array{$ids=implode(',',array_map('intval',$b));if(!$ids)return[];$sql="SELECT DISTINCT l.lesson_id id,COALESCE((SELECT value FROM translations WHERE table_name='lessons' AND table_id=l.lesson_id AND locale='fa' AND field='title' AND deleted_at IS NULL ORDER BY translation_id DESC LIMIT 1),CONCAT('درس ',l.lesson_id)) name FROM academy_branch_courses c JOIN lessons l ON l.lesson_id=c.lesson_id WHERE c.branch_id IN ($ids) AND c.deleted_at IS NULL AND l.deleted_at IS NULL ORDER BY l.lesson_id";return array_map(fn($x)=>['id'=>(int)$x['id'],'name'=>$x['name']],db()->query($sql)->fetchAll());}private function timeRangeOptions(array$b):array{$ids=implode(',',array_map('intval',$b));if(!$ids)return[];$sql="SELECT DISTINCT TIME_FORMAT(b.start_time,'%H:%i') start_time,TIME_FORMAT(b.end_time,'%H:%i') end_time FROM academy_branch_course_term_sessions s JOIN academy_branch_bookings b ON b.booking_id=s.booking_id JOIN academy_branch_course_terms t ON t.term_id=s.term_id JOIN academy_branch_courses c ON c.course_id=t.course_id WHERE c.branch_id IN ($ids) AND s.deleted_at IS NULL AND b.deleted_at IS NULL AND t.deleted_at IS NULL AND c.deleted_at IS NULL AND b.start_time IS NOT NULL AND b.end_time IS NOT NULL ORDER BY b.start_time,b.end_time";return array_map(fn($x)=>['start'=>$x['start_time'],'end'=>$x['end_time']],db()->query($sql)->fetchAll());}
private function tr(string$t,int$id,string$f):?string{return(new TranslationManager())->get($t,$id,$f,'fa');}private function setText(string$t,int$id,string$f,string$v,int$a):void{(new TranslationManager())->set($t,$id,$f,$v,'fa');}private function query(string$sql,array$b=[],bool$scalar=false):mixed{$s=db()->prepare($sql);$s->execute($b);return$scalar?$s->fetchColumn():$s->fetchAll();}
private function sessionNumber(array$r):int{$sql="SELECT COUNT(1) FROM academy_branch_course_term_sessions s2 JOIN academy_branch_bookings b2 ON b2.booking_id=s2.booking_id WHERE s2.term_id=? AND s2.deleted_at IS NULL AND b2.deleted_at IS NULL AND (b2.requested_date<? OR (b2.requested_date=? AND COALESCE(b2.start_time,'00:00:00')<COALESCE(?,'00:00:00')) OR (b2.requested_date=? AND COALESCE(b2.start_time,'00:00:00')=COALESCE(?,'00:00:00') AND s2.term_session_id<=?))";return(int)$this->query($sql,[(int)$r['term_id'],$r['requested_date'],$r['requested_date'],$r['start_time'],$r['requested_date'],$r['start_time'],(int)$r['term_session_id']],true);}
private function day(string$d):string{$days=['یکشنبه','دوشنبه','سه‌شنبه','چهارشنبه','پنجشنبه','جمعه','شنبه'];return$days[(int)date('w',strtotime($d))];}private function ordinal(int$n):string{$x=[1=>'اول',2=>'دوم',3=>'سوم',4=>'چهارم',5=>'پنجم',6=>'ششم',7=>'هفتم',8=>'هشتم',9=>'نهم',10=>'دهم',11=>'یازدهم',12=>'دوازدهم',13=>'سیزدهم',14=>'چهاردهم',15=>'پانزدهم',16=>'شانزدهم',17=>'هفدهم',18=>'هجدهم',19=>'نوزدهم',20=>'بیستم'];return$x[$n]??($n.'ام');}
